        ),
        ("", None, ""),
        ([], None, ""),
    ],
)
def test_show_envvar_shapes(runner, envvar, help_extra, error_hint):
    """A sequence of env vars is listed by name, and an empty ``envvar`` is
    not shown, in both the help and the error hint.
    """

    @click.command()
    @click.option("--units", type=int, envvar=envvar, show_envvar=True)
    def cmd(units):
        pass

    result = runner.invoke(cmd, ["--help"])
    assert not result.exception

    if help_extra is None:
        assert "env var" not in result.output
    else:
        assert help_extra in result.output

    result = runner.invoke(cmd, ["--units", "x"])
    assert result.exit_code == 2
    assert f"Invalid value for '--units'{error_hint}:" in result.output


